+const MIN_PORT = 1;
+const MAX_PORT = 65535;
+
+function parsePort(text: string, item: string): number {
+  if (!/^\d+$/.test(text)) {
+    throw new Error(`invalid port "${text}" in item "${item}"`);
+  }
+  const port = Number(text);
+  if (port < MIN_PORT || port > MAX_PORT) {
+    throw new Error(`port ${port} is outside ${MIN_PORT}-${MAX_PORT}`);
+  }
+  return port;
+}
+
+function parseItem(rawItem: string): PortRange {
+  const item = rawItem.trim();
+  if (item === "") {
+    throw new Error("empty item in port list");
+  }
+  const parts = item.split("-");
+  if (parts.length === 1) {
+    const port = parsePort(item, item);
+    return [port, port];
+  }
+  if (parts.length !== 2) {
+    throw new Error(`invalid range "${item}"`);
+  }
+  const from = parsePort(parts[0].trim(), item);
+  const to = parsePort(parts[1].trim(), item);
+  if (to < from) {
+    throw new Error(`range "${item}" ends before it starts`);
+  }
+  return [from, to];
+}

